import React, { useEffect, useState } from "react";

const CreateProfile = () => {

  const [formData, setFormData] = useState({
    firstName: "",
    lastName: "",
    email: ""
  });

  useEffect(() => {

    fetch("/db.json")
      .then((response) => response.json())
      .then((data) => {

        setFormData(data.userProfile.createProfile);

      })
      .catch((error) => {

        console.log("Error loading db.json:", error);

      });

  }, []);


  return (
    <div className="form-card">

      <div className="form-header">

        <h2>Create your user profile</h2>

        <p>
          Enter your basic profile information
        </p>

      </div>


      <form>

        <div className="form-row">

          <div className="form-group">

            <label>First name</label>

            <input
              type="text"
              name="firstName"
              placeholder="e.g Dhileep"
              value={formData.firstName}
              onChange={handleChange}
            />

          </div>


          <div className="form-group">

            <label>Last name</label>

            <input
              type="text"
              name="lastName"
              placeholder="e.g Reddy"
              value={formData.lastName}
              onChange={handleChange}
            />

          </div>

        </div>


        <div className="form-group">

          <label>Email</label>

          <div className="email-row">

            <input
              type="email"
              name="email"
              placeholder="e.g you@examplemail.com"
              value={formData.email}
              onChange={handleChange}
            />

            <button
              type="button"
              className="verify-button"
              onClick={handleVerify}
            >
              Verify
            </button>

          </div>

        </div>


        <div className="form-footer">

          <button
            type="button"
            className="save-button"
          >
            Save Profile
          </button>

        </div>

      </form>

    </div>
  );
};

export default CreateProfile;
